const ai = $node["AI Agent (Facturación)"].json.output;
let d;
try { const match = ai.match(/\{[\s\S]*\}/); d = JSON.parse(match ? match[0] : ai); } catch(e) { throw new Error('JSON Error'); }

const gv = (val) => (!val || String(val).trim() === '' || String(val).toLowerCase() === 'null') ? 'No disponible' : String(val).trim();
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = (v) => parseFloat(String(v || 0).replace(',','.')) || 0;
const q = String.fromCharCode(34);
const c = (t, v) => `<ss:Cell><ss:Data ss:Type=${q}${t}${q}>${v}</ss:Data></ss:Cell>`;

let row = `<ss:Row>`;
row += c('String', esc(gv(d.numero_factura))); row += c('String', esc(gv(d.fecha_factura))); row += c('String', esc(gv(d.fecha_vencimiento)));
row += c('String', esc(gv(d.emisor_nombre))); row += c('String', esc(gv(d.emisor_cif))); row += c('String', esc(gv(d.emisor_direccion)));
row += c('String', esc("INNOVATEK- ALEX CALVO GARCIA Y OTRA CB C")); row += c('String', esc("E20882726")); row += c('String', esc("ZALDIZURRETA 19, AZPIA, BEASAIN, GIPUZKOA, 20200"));
row += c('Number', String(num(d.base_imponible))); row += c('String', esc(gv(d.porcentaje_iva))); row += c('Number', String(num(d.cuota_iva)));
row += c('Number', String(num(d.total_factura))); row += c('String', esc(gv(d.forma_pago))); row += c('String', esc(gv(d.iban)));
row += `</ss:Row>`;

let xml = ""; try { xml = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf-8'); } catch (e) {}
if (xml.includes('>' + esc(gv(d.numero_factura)) + '</ss:Data>')) return [{ json: { success: false, reason: 'Duplicada' } }];

let finalXml = "";
const tableEndTag = /<\/(?:ss:)?Table\s*>/i;
if (xml && tableEndTag.test(xml)) { finalXml = xml.replace(tableEndTag, row + '\n</ss:Table>'); }
else {
  const hc = (t) => `<ss:Cell><ss:Data ss:Type="String">${t}</ss:Data></ss:Cell>`;
  let header = `<ss:Row>` + hc('Nº Factura')+hc('Fecha')+hc('Vencimiento')+hc('Proveedor')+hc('CIF Prov')+hc('Dir Prov')+hc('Cliente')+hc('CIF Cliente')+hc('Dir Cliente')+hc('Base')+hc('% IVA')+hc('Cuota IVA')+hc('Total')+hc('Pago')+hc('IBAN') + `</ss:Row>`;
  finalXml = `<?xml version="1.0" encoding="UTF-8"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Facturas"><ss:Table>${header}${row}</ss:Table></Worksheet></Workbook>`;
}

return [{ json: { success: true }, binary: { data: { data: Buffer.from(finalXml, 'utf-8').toString('base64'), fileName: 'tabla_excell_facturas.xls' } } }];
